cat > diag.js <<'FIN'
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const [mode, abs] = process.argv.slice(2);
const dir = path.resolve('d-' + mode);
fs.mkdirSync(dir, { recursive: true });
const ps1 = path.join(dir, 'f.ps1');
fs.writeFileSync(ps1, 'Set-Content -Path (Join-Path $PSScriptRoot "respaldo.txt") -Value corrido\n');
const c = spawn(mode === 'abs' ? abs : 'pwsh', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', ps1], { detached: mode !== 'attached', stdio: 'ignore', env: process.env, windowsHide: mode !== 'nohide' });
c.on('error', (e) => { fs.writeFileSync(path.join(dir, 'error.txt'), String(e.code || e.message)); });
if (mode === 'attached') c.on('close', () => process.exit(0));
else if (mode === 'wait') { c.unref(); setTimeout(() => process.exit(0), 8000); }
else { c.unref(); process.exit(0); }
FIN
